def seed(apps, schema_editor):
    """Clause lists of ISO 9001:2015 and ISO 14001:2015 (clause numbers and titles; the laboratory adds its own
    checklist wording on the master page)."""
    C = apps.get_model('QC', 'IaClause')
    for std, text in (('9001', ISO9001), ('14001', ISO14001)):
        if C.objects.filter(standard=std).exists():
            continue
        for i, line in enumerate(text.splitlines()):
            code, title = line.split('|', 1)
            C.objects.create(standard=std, code=code, title=title, requirement='', level=1 if '.' not in code else 2, order=(i + 1) * 10, active=True)


def unseed(apps, schema_editor):
    apps.get_model('QC', 'IaClause').objects.filter(standard__in=('9001', '14001')).delete()


